import{_ as l,a0 as o,w as p,s as n,ao as d,I as r,x as t,a1 as s,A as i}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const k=JSON.parse('{"title":"監測資料庫的健康和行為：有哪些重要指標？ | LCTT x X-CMD","titleTemplate":false,"description":"監測資料庫的健康和行為：有哪些重要指標？ | LCTT (201811) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"監測資料庫的健康和行為：有哪些重要指標？ | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"監測資料庫的健康和行為：有哪些重要指標？ | LCTT (201811) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201811/20181025 Monitoring database health and behavior- Which metrics matter","title":"監測資料庫的健康和行為：有哪些重要指標？","tag":"201811","desc":""},"relativePath":"201811/20181025 Monitoring database health and behavior- Which metrics matter.md","filePath":"[post].md"}'),m={name:"201811/20181025 Monitoring database health and behavior- Which metrics matter.md"};function h(u,e,f,c,b,g){const a=o("Link");return p(),n("div",null,[e[15]||(e[15]=d('<h1 id="監測資料庫的健康和行為-有哪些重要指標" tabindex="-1">監測資料庫的健康和行為：有哪些重要指標？ <a class="header-anchor" href="#監測資料庫的健康和行為-有哪些重要指標" aria-label="Permalink to “監測資料庫的健康和行為：有哪些重要指標？”">​</a></h1><blockquote><p>對資料庫的監測可能過於困難或者沒有找到關鍵點。本文將講述如何正確的監測資料庫。</p></blockquote><p><img src="https://opensource.com/sites/default/files/styles/image-full-size/public/lead-images/metrics_graph_stats_blue.png?itok=OKCc_60D" alt=""></p><p>我們沒有對資料庫討論過多少。在這個充滿監測儀器的時代，我們監測我們的應用程序、基礎設施、甚至我們的用户，但有時忘記我們的資料庫也值得被監測。這很大程度是因為資料庫表現的很好，以至於我們單純地信任它能把任務完成的很好。信任固然重要，但能夠證明它的表現確實如我們所期待的那樣就更好了。</p><p><img src="https://opensource.com/sites/default/files/styles/medium/public/uploads/image1_-_bffs.png?itok=BZQM_Fos" alt=""></p><h3 id="為什麼監測你的資料庫" tabindex="-1">為什麼監測你的資料庫？ <a class="header-anchor" href="#為什麼監測你的資料庫" aria-label="Permalink to “為什麼監測你的資料庫？”">​</a></h3><p>監測資料庫的原因有很多，其中大多數原因與監測系統的任何其他部分的原因相同：瞭解應用程序的各個組件中發生的什麼，會讓你成為更瞭解情況的，能夠做出明智決策的開發人員。</p><p><img src="https://opensource.com/sites/default/files/styles/medium/public/uploads/image5_fire.png?itok=wsip2Fa4" alt=""></p><p>更具體地説，資料庫是系統健康和行為的重要標誌。資料庫中的異常行為能夠指出應用程序中出現問題的區域。另外，當應用程序中有異常行為時，你可以利用資料庫的指標來迅速完成排除故障的過程。</p><h3 id="問題" tabindex="-1">問題 <a class="header-anchor" href="#問題" aria-label="Permalink to “問題”">​</a></h3><p>最輕微的調查揭示了監測資料庫的一個問題：資料庫有很多指標。説“很多”只是輕描淡寫，如果你是<ruby>史高治<rt>Scrooge McDuck</rt></ruby>（LCTT 譯註：史高治，唐老鴨的舅舅，以一毛不拔著稱），你不會放過任何一個可用的指標。如果這是<ruby>摔角狂熱<rt>Wrestlemania</rt></ruby> 比賽，那麼指標就是摺疊椅。監測所有指標似乎並不實用，那麼你如何決定要監測哪些指標？</p><p><img src="https://opensource.com/sites/default/files/styles/medium/public/uploads/image2_db_metrics.png?itok=Jd9NY1bt" alt=""></p><h3 id="解決方案" tabindex="-1">解決方案 <a class="header-anchor" href="#解決方案" aria-label="Permalink to “解決方案”">​</a></h3><p>開始監測資料庫的最好方式是認識一些基礎的資料庫指標。這些指標為理解資料庫的行為創造了良好的開端。</p><h3 id="吞吐量-資料庫做了多少" tabindex="-1">吞吐量：資料庫做了多少？ <a class="header-anchor" href="#吞吐量-資料庫做了多少" aria-label="Permalink to “吞吐量：資料庫做了多少？”">​</a></h3><p>開始檢測資料庫的最好方法是跟蹤它所接到請求的數量。我們對資料庫有較高期望；期望它能穩定的存儲數據，並處理我們拋給它的所有查詢，這些查詢可能是一天一次大規模查詢，或者是來自用户一天到晚的數百萬次查詢。吞吐量可以告訴我們資料庫是否如我們期望的那樣工作。</p><p>你也可以將請求按照類型（讀、寫、服務器端、客户端等）分組，以開始分析流量。</p><h3 id="執行時間-資料庫完成工作需要多長時間" tabindex="-1">執行時間：資料庫完成工作需要多長時間？ <a class="header-anchor" href="#執行時間-資料庫完成工作需要多長時間" aria-label="Permalink to “執行時間：資料庫完成工作需要多長時間？”">​</a></h3><p>這個指標看起來很明顯，但往往被忽視了。你不僅想知道資料庫收到了多少請求，還想知道資料庫在每個請求上花費了多長時間。 然而，參考上下文來討論執行時間非常重要：像 InfluxDB 這樣的時間序列資料庫中的慢與像 MySQL 這樣的關係型資料庫中的慢不一樣。InfluxDB 中的慢可能意味着毫秒，而 MySQL 的 <code>SLOW_QUERY</code> 變量的默認值是 10 秒。</p><p><img src="https://opensource.com/sites/default/files/styles/medium/public/uploads/image4_slow_is_relative.png?itok=9RkuzUi8" alt=""></p><p>監測執行時間和提高執行時間不一樣，所以如果你的應用程序中有其他問題需要修復，那麼請注意在優化上花費時間的誘惑。</p><h3 id="併發性-資料庫同時做了多少工作" tabindex="-1">併發性：資料庫同時做了多少工作？ <a class="header-anchor" href="#併發性-資料庫同時做了多少工作" aria-label="Permalink to “併發性：資料庫同時做了多少工作？”">​</a></h3><p>一旦你知道資料庫正在處理多少請求以及每個請求需要多長時間，你就需要添加一層複雜性以開始從這些指標中獲得實際值。</p><p>如果資料庫接收到十個請求，並且每個請求需要十秒鐘來完成，那麼資料庫是忙碌了 100 秒、10 秒，還是介於兩者之間？併發任務的數量改變了資料庫資源的使用方式。當你考慮連接和線程的數量等問題時，你將開始對資料庫指標有更全面的瞭解。</p><p>併發性還能影響延遲，這不僅包括任務完成所需的時間（執行時間），還包括任務在處理之前需要等待的時間。</p><h3 id="利用率-資料庫繁忙的時間百分比是多少" tabindex="-1">利用率：資料庫繁忙的時間百分比是多少？ <a class="header-anchor" href="#利用率-資料庫繁忙的時間百分比是多少" aria-label="Permalink to “利用率：資料庫繁忙的時間百分比是多少？”">​</a></h3><p>利用率是由吞吐量、執行時間和併發性的峯值所確定的資料庫可用的頻率，或者資料庫太忙而不能響應請求的頻率。</p><p><img src="https://opensource.com/sites/default/files/styles/medium/public/uploads/image6_telephone.png?itok=YzdpwUQP" alt=""></p><p>該指標對於確定資料庫的整體健康和性能特別有用。如果只能在 80% 的時間內響應請求，則可以重新分配資源、進行優化工作，或者進行更改以更接近高可用性。</p><h3 id="好消息" tabindex="-1">好消息 <a class="header-anchor" href="#好消息" aria-label="Permalink to “好消息”">​</a></h3><p>監測和分析似乎非常困難，特別是因為我們大多數人不是資料庫專家，我們可能沒有時間去理解這些指標。但好消息是，大部分的工作已經為我們做好了。許多資料庫都有一個內部性能資料庫（Postgres：<code>pg_stats</code>、CouchDB：<code>Runtime_Statistics</code>、InfluxDB：<code>_internal</code> 等），資料庫工程師設計該資料庫來監測與該特定資料庫有關的指標。你可以看到像慢速查詢的數量一樣廣泛的內容，或者像資料庫中每個事件的平均微秒一樣詳細的內容。</p><h3 id="結論" tabindex="-1">結論 <a class="header-anchor" href="#結論" aria-label="Permalink to “結論”">​</a></h3><p>資料庫創建了足夠的指標以使我們需要長時間研究，雖然內部性能資料庫充滿了有用的信息，但並不總是使你清楚應該關注哪些指標。從吞吐量、執行時間、併發性和利用率開始，它們為你提供了足夠的信息，使你可以開始瞭解你的資料庫中的情況。</p><p><img src="https://opensource.com/sites/default/files/styles/medium/public/uploads/image3_3_hearts.png?itok=iHF-OSwx" alt=""></p><p>你在監視你的資料庫嗎？你發現哪些指標有用？告訴我吧！</p><hr>',36)),r("p",null,[e[1]||(e[1]=t("via: ",-1)),s(a,{href:"https://opensource.com/article/18/10/database-metrics-matter"},{default:i(()=>[...e[0]||(e[0]=[t("https://opensource.com/article/18/10/database-metrics-matter",-1)])]),_:1})]),r("p",null,[e[6]||(e[6]=t("作者：",-1)),s(a,{href:"https://opensource.com/users/thekatertot"},{default:i(()=>[...e[2]||(e[2]=[t("Katy Farmer",-1)])]),_:1}),e[7]||(e[7]=t(" 選題：",-1)),s(a,{href:"https://github.com/lujun9972"},{default:i(()=>[...e[3]||(e[3]=[t("lujun9972",-1)])]),_:1}),e[8]||(e[8]=t(" 譯者：",-1)),s(a,{href:"https://github.com/ChiZelin"},{default:i(()=>[...e[4]||(e[4]=[t("ChiZelin",-1)])]),_:1}),e[9]||(e[9]=t(" 校對：",-1)),s(a,{href:"https://github.com/wxy"},{default:i(()=>[...e[5]||(e[5]=[t("wxy",-1)])]),_:1})]),r("p",null,[e[12]||(e[12]=t("本文由 ",-1)),s(a,{href:"https://github.com/LCTT/TranslateProject"},{default:i(()=>[...e[10]||(e[10]=[t("LCTT",-1)])]),_:1}),e[13]||(e[13]=t(" 原創編譯，",-1)),s(a,{href:"https://linux.cn/"},{default:i(()=>[...e[11]||(e[11]=[t("Linux中國",-1)])]),_:1}),e[14]||(e[14]=t(" 榮譽推出",-1))])])}const T=l(m,[["render",h]]);export{k as __pageData,T as default};
